diff --git a/templates/shared_shell.css b/templates/shared_shell.css
index 16d9de6384e1..88a0fd9e836f 100644
--- a/templates/shared_shell.css
+++ b/templates/shared_shell.css
@@ -8,7 +8,5 @@ html[data-mmx-shared-shell="1"] .landing-nav {
   display: none !important;
 }
 html[data-mmx-shared-shell="1"] {
-  --nav-offset: 0px;
-  --nav-height: 0px;
   --mmx-shared-shell-css-ready: 1;
 }
diff --git a/tests/js/shared_shell_bridge.test.cjs b/tests/js/shared_shell_bridge.test.cjs
index f1a12d290d07..464b53c02aad 100644
--- a/tests/js/shared_shell_bridge.test.cjs
+++ b/tests/js/shared_shell_bridge.test.cjs
@@ -356,7 +356,6 @@ test('valid INIT: chrome suppression, context, READY shape', () => {
   const css = CSS;
   assert.ok(css.indexOf('.site-nav') !== -1 && css.indexOf('[data-mmx-all-tools]') !== -1 && css.indexOf('#mmx-all-tools') !== -1);
   assert.ok(css.indexOf('.public-nav') !== -1 && css.indexOf('.landing-nav') !== -1);
-  assert.ok(css.indexOf('--nav-offset: 0px') !== -1 && css.indexOf('--nav-height: 0px') !== -1);
   assert.ok(css.indexOf('header') === -1);
   const mainNav = 'body > nav.nav[aria-label="Main"]';
   assert.ok(css.includes('html[data-mmx-shared-shell="1"] ' + mainNav + ','));
